    "lib/layer1_backtesting/test_modules.js": function(module, exports, require) {
      "use strict";

      /**
       * The four agreed test modules as executable contracts (research only).
       *
       * A test module is not a tab label. Each entry says what the module consumes, which session markets it
       * scores, and what it needs before it can be scored at all. The controller reads this file when a run asks
       * for a test selection, so choosing a module changes what is computed - which markets are scored and which
       * modules are recorded as not run - rather than only what an experiment record says about itself.
       *
       * Two distinctions are kept explicit because collapsing them would overstate what a run proved:
       *   - `per_record: "market_outcomes"` modules are scored inside a replayed record from the committed panel;
       *   - `per_record: "trade_paths"` modules need a 5-minute tape and a level ladder per market, so a record
       *     that carries no `trade_paths` is recorded as `blocked_on_history`, never as a zero.
       *
       * Nothing here reads a file, the network or a production path.
       */

      const MODULES = Object.freeze([
        Object.freeze({
          id: "dxy_direction_broker_cfd",
          ordinal: 1,
          label: "USD direction on the broker DXY.cash series",
          markets: Object.freeze([]),
          per_record: "not_run",
          requires: Object.freeze(["broker_dxy_h1_closes"]),
          reason:
            "the replayed panel carries no broker DXY outcome per morning; test 1 is scored once per run from the broker's one-hour candles, not inside a per-morning record"
        }),
        Object.freeze({
          id: "four_markets",
          ordinal: 2,
          label: "USD-only opposite-direction mapping across the configured markets",
          markets: Object.freeze(["*"]),
          market_scope: "all_configured",
          per_record: "market_outcomes",
          requires: Object.freeze([]),
          reason: null
        }),
        Object.freeze({
          id: "l2l_full_5r",
          ordinal: 3,
          label: "Original Layer 2 levels with the frozen 5R rules",
          markets: Object.freeze([]),
          per_record: "trade_paths",
          simulation: "full_5r",
          requires: Object.freeze(["m5_tape", "level_ladder"]),
          reason:
            "a trade path needs a 5-minute tape and a level ladder archived before the setup; neither exists for these mornings"
        }),
        Object.freeze({
          id: "l2l_half_3r",
          ordinal: 4,
          label: "Original levels plus midpoints with the frozen 3R rules",
          markets: Object.freeze([]),
          per_record: "trade_paths",
          simulation: "half_3r",
          requires: Object.freeze(["m5_tape", "level_ladder"]),
          reason:
            "a trade path needs a 5-minute tape and a level ladder archived before the setup; neither exists for these mornings"
        })
      ]);

      const MODULE_IDS = Object.freeze(MODULES.map((module) => module.id));
      const DEFAULT_SELECTION = MODULE_IDS;

      function byId(id) {
        return MODULES.find((module) => module.id === id) || null;
      }

      /**
       * Turn a requested selection into module definitions.
       *
       * A webhook body, a query string or a dashboard checkbox group all arrive as strings, so a string is
       * accepted. An unknown module is an error: a run must never report a test it did not execute, and a typo
       * must not silently fall back to the full set. An empty request means "all four", which is the committed
       * default the published run used.
       */
      function resolveModules(requested) {
        if (requested === undefined || requested === null || requested === "") return MODULES.slice();
        const raw = Array.isArray(requested) ? requested : String(requested).split(",");
        const ids = [];
        for (const entry of raw) {
          const id = entry && typeof entry === "object" && entry.id ? String(entry.id) : String(entry).trim();
          if (!id) continue;
          if (!byId(id)) {
            throw new Error(`unknown test module ${JSON.stringify(id)}; the committed modules are ${MODULE_IDS.join(", ")}`);
          }
          if (!ids.includes(id)) ids.push(id);
        }
        if (ids.length === 0) throw new Error("a run must select at least one test module");
        return ids.map(byId);
      }

      /** The committed market order a caller gets when it passes no configuration of its own. */
      const DEFAULT_MARKET_ORDER = Object.freeze(["EURUSD", "XAUUSD", "BTCUSD", "NAS100"]);

      /**
       * The markets the selection scores, in the order the caller declares.
       *
       * A module that declares `"*"` scores every configured market, so a run whose dataset carries the eight-market
       * matrix is scored on eight and a run whose dataset declares four is scored on four. A module that names its
       * markets scores only those. Nothing here knows a market by heart.
       */
      function marketsFor(modules, marketOrder) {
        const order = Array.isArray(marketOrder) && marketOrder.length ? marketOrder : DEFAULT_MARKET_ORDER;
        const wanted = new Set();
        for (const module of modules) {
          if (module.markets.includes("*")) {
            for (const market of order) wanted.add(market);
            continue;
          }
          for (const market of module.markets) wanted.add(market);
        }
        return order.filter((market) => wanted.has(market));
      }

      /** The frozen simulation rules the selection asks for, in module order. */
      function simulationsFor(modules) {
        return modules.filter((module) => module.simulation).map((module) => module.simulation);
      }

      function idsOf(modules) {
        return modules.map((module) => module.id);
      }

      /**
       * What happened to each selected module on one record.
       *
       * `scored` needs a stored result; `no_outcome` is a scored module whose morning had no readable outcome;
       * `blocked_on_history` is a path module without a tape; `not_run` is a module the record cannot carry.
       * A module that was not selected is not reported here at all, so a reader can tell "not asked" from "asked
       * and refused".
       */
      function moduleRunStates({ modules, results, session } = {}) {
        const selected = Array.isArray(modules) && modules.length > 0 ? modules : resolveModules(null);
        const rows = Array.isArray(results) ? results : [];
        const tradePaths = session && session.trade_paths && typeof session.trade_paths === "object"
          ? session.trade_paths
          : null;
        return selected.map((module) => {
          if (module.per_record === "market_outcomes") {
            const declared = module.markets.includes("*")
              ? rows.length
                ? [...new Set(rows.map((row) => row.market))]
                : Object.keys((session && session.outcomes) || {})
              : module.markets.slice();
            const scored = declared
              .map((market) => rows.find((row) => row && row.market === market))
              .filter(Boolean);
            const anyOutcome = scored.some((row) => ["hit", "miss", "flat"].includes(row.result));
            return {
              id: module.id,
              ordinal: module.ordinal,
              state: anyOutcome ? "scored" : "no_outcome",
              markets: declared,
              reason: anyOutcome ? null : "no selected market had a readable outcome for this morning"
            };
          }
          if (module.per_record === "trade_paths") {
            const markets = tradePaths && Array.isArray(tradePaths.markets) ? tradePaths.markets : [];
            const usable = markets.filter((market) => tradePaths[market] && Array.isArray(tradePaths[market].candles));
            return {
              id: module.id,
              ordinal: module.ordinal,
              state: usable.length > 0 ? "scored" : "blocked_on_history",
              simulation: module.simulation,
              markets: usable,
              reason: usable.length > 0 ? null : module.reason
            };
          }
          return {
            id: module.id,
            ordinal: module.ordinal,
            state: "not_run",
            markets: [],
            reason: module.reason
          };
        });
      }

      module.exports = {
        MODULES,
        MODULE_IDS,
        DEFAULT_SELECTION,
        DEFAULT_MARKET_ORDER,
        byId,
        resolveModules,
        marketsFor,
        simulationsFor,
        idsOf,
        moduleRunStates
      };

    },
    "lib/usd_l1_votes.js": function(module, exports, require) {
      /**
       * The challenger's rule interpreter, shared by the research engine and the dashboard panel.
       *
       * The rules themselves are data, not code: a mechanism is an input, a declared USD direction for each
       * threshold and a weight. This file only interprets those declarations. The engine scores a session with
       * it, the panel re-scores a session from the values saved in the artefact with the same file, so "re-run
       * from the saved inputs" is one implementation rather than a second opinion.
       *
       * Research only. Nothing here reads a file, the network, the warehouse or a production path.
       */
      (function (root, factory) {
        if (typeof module === "object" && module.exports) {
          module.exports = factory();
          return;
        }
        root.UsdL1Votes = factory();
      })(typeof globalThis !== "undefined" ? globalThis : this, function () {
        "use strict";

        const VOTES_VERSION = "usd-l1-votes-v1";

        /** Ordering used by a vote spec: `gt` is "above", `lt` is "below", `gte`/`lte` are inclusive. */
        function compare(spec, value) {
          if (spec.when === "gt") return value > spec.value;
          if (spec.when === "gte") return value >= spec.value;
          if (spec.when === "lt") return value < spec.value;
          if (spec.when === "lte") return value <= spec.value;
          if (spec.when === "abs_gt") return Math.abs(value) > spec.value;
          throw new Error(`unknown vote comparator ${spec.when}`);
        }

        /**
         * Interpret one mechanism's vote.
         *
         * @param {object[]} spec ordered branches; the first branch that matches decides the vote.
         * @param {number} value the input as it stood at the cutoff.
         * @returns {number} +1 for a bullish USD reading, -1 for bearish, 0 for no reading.
         */
        function interpretVote(spec, value) {
          if (!Number.isFinite(value)) return null;
          for (const branch of spec) {
            if (compare(branch, value)) return branch.usd;
          }
          return 0;
        }

        /** Band one call from its agreement and participation, exactly as the frozen table declares. */
        function convictionFor(rules, agreement, participation) {
          for (const band of rules.conviction_bands) {
            if (agreement >= band.min_agreement && participation >= band.min_participation) return band.conviction;
          }
          return 1;
        }

        /**
         * Score one snapshot from the declared mechanisms and rules.
         *
         * @param {object} options
         * @param {object[]} options.mechanisms the frozen mechanism list, each with `id`, `input`, `vote_spec`, `weight`.
         * @param {object} options.rules equal weight, minimum usable mechanisms, agreement deadband, conviction bands.
         * @param {object} options.values the input values at the cutoff.
         * @returns {object} the call record: direction, conviction, raw score, votes and the reason for no call.
         */
        function evaluateFromSpecs({ mechanisms, rules, values }) {
          const inputs = values || {};
          const votes = mechanisms.map((mechanism) => {
            const raw = inputs[mechanism.input];
            const hasValue = Number.isFinite(raw);
            return {
              id: mechanism.id,
              label: mechanism.label,
              factor: mechanism.factor,
              input: mechanism.input,
              rule: mechanism.rule,
              threshold: mechanism.threshold,
              weight: Number.isFinite(mechanism.weight) ? mechanism.weight : rules.equal_weight,
              vote_spec: mechanism.vote_spec,
              value: hasValue ? raw : null,
              vote: hasValue ? interpretVote(mechanism.vote_spec, raw) : null,
              state: hasValue ? "usable" : "missing"
            };
          });

          const usable = votes.filter((entry) => entry.state === "usable");
          const missing = votes.filter((entry) => entry.state === "missing").map((entry) => entry.input);
          const totalWeight = votes.reduce((total, entry) => total + entry.weight, 0);
          const usableWeight = usable.reduce((total, entry) => total + entry.weight, 0);
          const participation = totalWeight > 0 ? usableWeight / totalWeight : 0;
          // Weight-aware since 2026-11-10: a family of two mechanisms can share one unit of say. Every equal-weight
          // spec (challenger v0, all weights 1) reduces exactly to the integer count it scored before.
          const net = Math.round(usable.reduce((total, entry) => total + entry.vote * entry.weight, 0) * 10000) / 10000;
          const agreement = usableWeight > 0 ? Math.abs(net) / usableWeight : 0;

          const base = {
            mechanisms: votes,
            usable_mechanisms: usable.length,
            mechanism_count: mechanisms.length,
            usable_weight: Math.round(usableWeight * 10000) / 10000,
            total_weight: Math.round(totalWeight * 10000) / 10000,
            participation: Math.round(participation * 10000) / 10000,
            agreement: Math.round(agreement * 10000) / 10000,
            raw_score: net,
            missing_inputs: missing,
            inputs_used: usable.map((entry) => entry.input)
          };

          if (usable.length < rules.min_usable_mechanisms) {
            return {
              ...base,
              direction: "NO_CALL",
              conviction: null,
              reason:
                `only ${usable.length} of ${mechanisms.length} mechanisms had a value at this cutoff and the frozen ` +
                `minimum is ${rules.min_usable_mechanisms}, so no call is made and the missing inputs are named`
            };
          }

          if (agreement < rules.agreement_deadband) {
            return {
              ...base,
              direction: "NO_CALL",
              conviction: null,
              reason:
                `the mechanisms split ${net > 0 ? "+" : ""}${net} across ${usable.length} live inputs, inside the frozen ` +
                `${rules.agreement_deadband} agreement deadband, so the day is recorded as no call rather than a coin toss`
            };
          }

          return {
            ...base,
            direction: net > 0 ? "BULLISH" : "BEARISH",
            conviction: convictionFor(rules, agreement, participation),
            reason:
              `${usable.length} of ${mechanisms.length} mechanisms live, net ${net > 0 ? "+" : ""}${net} ` +
              `(${Math.round(agreement * 100)}% agreement, ${Math.round(participation * 100)}% participation)`
          };
        }

        return { VOTES_VERSION, compare, interpretVote, convictionFor, evaluateFromSpecs };
      });

    },
    "backtester/lib/usd_session_engine_interface.js": function(module, exports, require) {
      "use strict";

      /**
       * Session-target and as-of-cutoff interfaces for the USD session engine (research only, 2026-10-13;
       * session horizon corrected to 05:00 London to 05:00 London on 2026-10-14).
       *
       * This file is an interface contract, not the engine. It exists so that every later implementation of a
       * historical or prospective run resolves the two endpoints and the as-of rule in one place, and so a
       * leakage mistake is caught by construction rather than by review.
       *
       * Both ends of the session are wall-clock local times in Europe/London: the session runs from 05:00 London
       * on its own local date to 05:00 London on the next local date. Offsets are derived from declared
       * transition instants, never from a fixed hour count.
       *
       * America/New_York is no longer part of the session definition. Its transitions are kept in
       * ZONE_TRANSITIONS only because the macro as-of builder times the Fed's H.10 release in that zone.
       *
       * Nothing here reads the network, the warehouse, the dispatcher or a production path.
       */

      const SESSION_CONTRACT = Object.freeze({
        cutoff_local: "05:00",
        cutoff_zone: "Europe/London",
        endpoint_local: "05:00",
        endpoint_zone: "Europe/London",
        endpoint_day_offset: 1,
        nominal_hours: 24,
        session_start_weekdays: [1, 2, 3, 4, 5],
        session_start_rule: "a session starts on Monday to Friday only, so the Saturday and Sunday starts are never sessions; the Saturday start is the only one that can contain a London DST transition, which is why every eligible session is exactly 24 hours"
      });

      /**
       * Declared daylight-saving transitions from the official rules (last Sunday of March/October for the EU,
       * second Sunday of March / first Sunday of November for the US). Extend by year; a missing year throws
       * rather than guessing an offset.
       */
      const ZONE_TRANSITIONS = Object.freeze({
        "Europe/London": {
          spring_forward_utc: { 2023: "2023-03-26T01:00:00Z", 2024: "2024-03-31T01:00:00Z", 2025: "2025-03-30T01:00:00Z", 2026: "2026-03-29T01:00:00Z", 2027: "2027-03-28T01:00:00Z" },
          fall_back_utc: { 2023: "2023-10-29T01:00:00Z", 2024: "2024-10-27T01:00:00Z", 2025: "2025-10-26T01:00:00Z", 2026: "2026-10-25T01:00:00Z", 2027: "2027-10-31T01:00:00Z" },
          standard_offset_minutes: 0,
          summer_offset_minutes: 60,
          standard_abbrev: "GMT",
          summer_abbrev: "BST"
        },
        "America/New_York": {
          spring_forward_utc: { 2023: "2023-03-12T07:00:00Z", 2024: "2024-03-10T07:00:00Z", 2025: "2025-03-09T07:00:00Z", 2026: "2026-03-08T07:00:00Z", 2027: "2027-03-14T07:00:00Z" },
          fall_back_utc: { 2023: "2023-11-05T06:00:00Z", 2024: "2024-11-03T06:00:00Z", 2025: "2025-11-02T06:00:00Z", 2026: "2026-11-01T06:00:00Z", 2027: "2027-11-07T06:00:00Z" },
          standard_offset_minutes: -300,
          summer_offset_minutes: -240,
          standard_abbrev: "EST",
          summer_abbrev: "EDT"
        }
      });

      class SessionContractError extends Error {
        constructor(message) {
          super(message);
          this.name = "SessionContractError";
        }
      }

      function offsetMinutesAt(instantUtcMs, zone) {
        const zoneRule = ZONE_TRANSITIONS[zone];
        if (!zoneRule) throw new SessionContractError(`unknown zone ${zone}`);
        const utcYear = new Date(instantUtcMs).getUTCFullYear();
